                texto += `Pai: ${r.NOME_PAI || "Não informado"}\n`;
                texto += `Título Eleitor: ${r.TITULO_ELEITOR || "Não informado"}\n`;
                texto += `Óbito: ${r.DT_OBITO || "Não informado"}\n\n`;
