                    movieDetails += `📝 **Sinopse:** ${movie.synopsis}\n`;
                    movieDetails += `🎬 **Direção:** ${movie.directors}\n`;
                    movieDetails += `🎭 **Elenco:** ${movie.cast}\n\n`;
